<style>
:root{color-scheme:light;--ink:#17283e;--muted:#6b7b8e;--line:#e7ecf2;--blue:#245be7;--bg:#f6f8fc;--green:#16836b}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.8 Tahoma,'Segoe UI',Arial,sans-serif}button,input,select{font:inherit}button,a,input,select{touch-action:manipulation}button,a{ -webkit-tap-highlight-color:transparent}button{cursor:pointer}a{color:inherit;text-decoration:none}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #92b6ff;outline-offset:3px}button:disabled{opacity:.5;cursor:wait}[hidden]{display:none!important}.analytics-shell{display:flex;min-height:100vh}.analytics-sidebar{width:235px;flex:0 0 235px;background:white;border-left:1px solid var(--line);padding:32px 20px;position:sticky;top:0;height:100dvh;display:flex;flex-direction:column;gap:20px}.brand{display:flex;align-items:center;gap:12px;font-size:27px;font-weight:800;direction:ltr;justify-content:flex-end}.brand small{display:block;font-size:11px;font-weight:400;color:var(--muted);direction:rtl}.brand-icon{display:grid;place-items:center;width:43px;height:43px;border-radius:14px;background:var(--blue);color:white;font-size:29px}.sidebar-label{color:#94a0b0;font-size:11px;margin-top:28px}.analytics-sidebar nav{display:grid;gap:10px}.analytics-sidebar nav a{padding:12px;border-radius:10px;color:var(--muted);font-size:12px;display:flex;align-items:center;gap:12px}.analytics-sidebar nav span{font-size:22px;line-height:1}.analytics-sidebar nav a:hover,.analytics-sidebar nav a.selected{background:#edf3ff;color:var(--blue)}.sidebar-note{margin-top:auto;border:1px solid var(--line);border-radius:14px;padding:16px;font-size:12px}.sidebar-note p{color:var(--muted);font-size:11px;margin-bottom:0}.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#1aa882;margin-left:6px}.admin-person{display:flex;align-items:center;gap:10px;font-size:12px;border-top:1px solid var(--line);padding-top:20px}.admin-person>span{background:#edf1fa;border-radius:50%;width:36px;height:36px;display:grid;place-items:center}.admin-person small{display:block;color:var(--muted);font-size:10px}.analytics-main{min-width:0;width:100%;padding:0 36px 40px;max-width:1800px;margin:auto}.analytics-top{display:flex;justify-content:space-between;gap:10px;align-items:center;min-height:78px;border-bottom:1px solid var(--line);font-size:12px;color:var(--muted)}.analytics-top b{padding:0 12px;color:#c2c9d4}.live-label{color:var(--green);font-size:11px}.page-intro{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:30px 0 24px}.eyebrow{font-size:11px;color:var(--blue);font-weight:700}h1{font-size:29px;letter-spacing:-1px;margin:6px 0}h2{font-size:16px;margin:0}p{margin:4px 0;color:var(--muted)}.page-intro p{font-size:12px}.panel{background:white;border:1px solid var(--line);border-radius:17px;padding:24px;margin-bottom:22px;min-width:0;box-shadow:0 3px 12px #182c4d03}.button{border:1px solid var(--line);border-radius:9px;min-height:42px;padding:9px 18px;font-size:12px;white-space:nowrap}.primary{background:var(--blue);color:white;border-color:var(--blue)}.secondary{background:white;color:var(--ink)}.filters{display:flex;flex-wrap:wrap;align-items:end;gap:14px;padding:18px 20px}.filters label,label.search-label{font-size:11px;color:var(--muted)}.filters .shop-filter{flex:1;min-width:170px}.filters input,.filters select,.section-head input,.section-head select{display:block;min-height:42px;border:1px solid #dce3ec;background:white;border-radius:8px;padding:7px 11px;color:var(--ink);width:100%;margin-top:5px;font-size:13px}.presets{display:flex;gap:5px;align-self:end}.presets button{border:0;color:var(--blue);background:#f1f5ff;border-radius:7px;padding:11px 9px;font-size:11px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:22px 0}.metric{padding:20px;background:white;border:1px solid var(--line);border-radius:15px;position:relative;min-height:143px}.metric-label{color:var(--muted);font-size:12px;display:flex;justify-content:space-between;gap:6px}.metric-icon{width:27px;height:27px;display:grid;place-items:center;background:#edf3ff;color:var(--blue);border-radius:8px}.metric-value{font-size:29px;font-weight:700;line-height:1.4;margin:12px 0 7px;direction:ltr;text-align:right;overflow-wrap:anywhere}.metric small{font-size:10px;color:var(--muted)}.metric:first-child{background:var(--blue);color:white;border:0}.metric:first-child .metric-label,.metric:first-child small{color:#dbe5ff}.metric:first-child .metric-icon{background:#ffffff24;color:white}.overview-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(0,1fr);gap:22px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:24px}.section-head p{font-size:11px;margin-top:6px}.section-head label{font-size:11px}.pill{padding:4px 10px;background:#f0f4fa;border-radius:7px;color:var(--muted);font-size:10px;white-space:nowrap}.sales-chart{height:230px;direction:ltr}.sales-chart svg{width:100%;height:195px;overflow:visible}.chart-labels{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin-top:12px}.comparison{margin-top:20px;border-top:1px solid var(--line);padding-top:14px;font-size:12px;color:var(--muted)}.status-list{display:grid;gap:17px}.status-row>div{display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px}.bar{height:6px;background:#edf1f7;border-radius:20px;overflow:hidden}.bar i{height:100%;display:block;background:var(--blue);border-radius:20px}.status-row:nth-child(2n) .bar i{background:#28ab94}.status-row:nth-child(3n) .bar i{background:#f3b75e}.note{font-size:10px;color:var(--muted);background:#f7f9fc;border-radius:9px;padding:12px;margin-top:24px}.table-scroll{max-width:100%;overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:right;white-space:nowrap;font-size:12px}th{background:#f8fafd;color:#8190a4;font-weight:400;font-size:11px;padding:13px 14px;border-bottom:1px solid var(--line)}td{padding:17px 14px;border-bottom:1px solid #f0f3f7}tr:last-child td{border:0}td button{background:none;border:0;color:var(--blue);font-weight:700;text-align:right}.shop-cell{display:flex;align-items:center;gap:10px}.shop-avatar{width:33px;height:33px;background:#eff3fb;color:#4672a9;border-radius:10px;display:grid;place-items:center}.shop-cell small{display:block;font-size:10px;color:var(--muted);font-weight:400}.rank-list{display:grid;gap:18px}.rank-item{display:flex;align-items:center;gap:12px;font-size:12px}.rank-number{width:30px;height:30px;background:#f2f5fb;color:var(--muted);border-radius:8px;display:grid;place-items:center}.rank-name{flex:1;min-width:0;overflow-wrap:anywhere}.rank-name small{display:block;color:var(--muted);font-size:10px}.rank-item>b{color:var(--blue);white-space:nowrap}.detail-stats>div{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);font-size:12px}.detail-stats>div span{color:var(--muted)}.text-link{color:var(--blue);font-size:12px}.activity-entry{display:grid;grid-template-columns:32px minmax(0,1fr) auto;gap:12px;padding:18px 0;border-bottom:1px solid var(--line)}.activity-dot{height:30px;width:30px;display:grid;place-items:center;border-radius:50%;background:#eff4ff;color:var(--blue)}.activity-entry h3{font-size:12px;margin:0;overflow-wrap:anywhere}.activity-entry p,.activity-entry time{font-size:10px;color:var(--muted)}.activity-entry button{background:none;border:0;color:var(--blue);padding:0;font-size:11px}.activity-entry details{font-size:11px;color:var(--muted);overflow-wrap:anywhere}.activity-entry pre{white-space:pre-wrap;direction:ltr;text-align:left;max-width:100%;font-size:11px}.activity-list{margin-bottom:15px}.empty{padding:35px 10px;color:var(--muted);text-align:center;font-size:12px}.notice{padding:14px 18px;border-radius:10px;margin:15px 0;font-size:12px}.error{background:#fff2ef;color:#a13428;border:1px solid #f5d9d2}.data-notes{padding:10px 4px 60px;font-size:11px;color:var(--muted)}.data-notes p{margin-top:8px}.order-dialog{color:var(--ink);background:white;border:1px solid var(--line);border-radius:18px;width:min(620px,calc(100% - 24px));max-height:calc(100dvh - 32px);padding:24px;overflow:auto}.order-dialog::backdrop{background:#12253c88}.dialog-head{display:flex;justify-content:space-between;align-items:center;gap:15px}.dialog-head button{border:0;background:#f2f5f9;border-radius:50%;width:40px;height:40px;font-size:24px}.order-detail-line{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line);padding:12px 0;font-size:12px;overflow-wrap:anywhere}.order-detail-line span{color:var(--muted);flex-shrink:0}.order-detail-line b{text-align:left;min-width:0;overflow-wrap:anywhere}.order-dialog .button{display:inline-block;margin-top:20px}
@media(min-width:1550px){.analytics-main{padding-inline:50px}.metrics{gap:22px}}
@media(max-width:1150px){.analytics-sidebar{width:195px;flex-basis:195px;padding:25px 14px}.analytics-main{padding-inline:22px}.overview-grid{grid-template-columns:minmax(0,1.3fr) minmax(0,1fr)}.metric{padding:15px}.metric-value{font-size:24px}}
